def backfill_prepaid_and_profit_sharing(apps, schema_editor):
    Stall = apps.get_model("market", "Stall")
    Order = apps.get_model("market", "Order")
    Product = apps.get_model("market", "Product")

    Stall.objects.filter(is_demo=True, transaction_enabled=True).update(
        simulation_payment_enabled=True,
        auto_accept_orders=True,
    )

    for order in Order.objects.all().iterator(chunk_size=500):
        bps = 500
        fee_cents = min(order.total_cents, (order.total_cents * bps + 5000) // 10000)
        net_cents = max(0, order.total_cents - fee_cents)
        updates = {
            "platform_fee_bps": bps,
            "platform_fee_cents": fee_cents,
            "merchant_net_cents": net_cents,
        }
        if order.payment_status == "paid":
            if order.status == "completed":
                updates["settlement_status"] = "settled"
                updates["settled_at"] = order.completed_at or order.paid_at or order.created_at
                if not order.completed_by:
                    updates["completed_by"] = "merchant_code"
            elif order.status in ("cancelled", "rejected"):
                updates["settlement_status"] = "reversed"
            else:
                updates["settlement_status"] = "escrow"
        elif order.payment_status == "refunded":
            updates["settlement_status"] = "reversed"
        elif order.payment_status == "unpaid" and order.status in ("pending", "preparing", "ready"):
            if not order.inventory_released:
                for item in order.items.order_by("product_id"):
                    Product.objects.filter(pk=item.product_id).update(
                        stock=F("stock") + item.quantity,
                        stock_version=F("stock_version") + 1,
                    )
                updates["inventory_released"] = True
            updates["status"] = "cancelled"
            updates["cancel_requested"] = False
            updates["cancel_reason"] = "系统升级为在线预付模式，历史未付款测试单已自动关闭"
        Order.objects.filter(pk=order.pk).update(**updates)


